#include <algorithm>
#include <vector>

double median(std::vector<int> values)
{
    std::sort(values.begin(), values.end());
    const std::size_t middle{ values.size() / 2 };
    if (values.size() % 2 == 1)
    {
        return values[middle];
    }
    return (values[middle - 1] + values[middle]) / 2.0;
}

unitTests:
TEST("odd count") { CHECK_NEAR(median({ 5, 1, 3 }), 3.0, 1e-12); }
TEST("even count") { CHECK_NEAR(median({ 4, 1, 3, 2 }), 2.5, 1e-12); }
TEST("one value") { CHECK_NEAR(median({ 9 }), 9.0, 1e-12); }
TEST("the caller's vector is untouched") { std::vector<int> v{ 3, 1, 2 }; median(v); CHECK_EQ(v, (std::vector<int>{ 3, 1, 2 })); }

